card_source:
// 拾意 · 现场造卡（shiyi-live）0.8.6
// 一句话进去，一张卡出来。
//
// 0.8.6 · 自动读群消息（2026-10-11，与桌面「自动读邮件」同构）
//   手机是日常那一个，信息源是群消息。以前是「你点一条，它才读」——
//   现在脚本一跑起来就每几秒自己看一眼群：群里来了新消息，它自己读到就造卡。
//   首启只登记基线（房间里原有的旧消息不刷成卡），拾意自己发回群的那条结论也不重复造卡。
//   桌面收邮件、手机收群消息，两个场景，同一套做法。
//
// 0.8.1 · 适配手机壳（Rinx）：同一个「问 AI」，多一条路（2026-10-11）
//   手机壳（Rinx）不给 model.complete（那个由桌面壳 OctoSense shell 提供），
//   但它自带设备助手，服务名 octos.turn.start：只收一句话 {text}、回一段文本。
//   于是探测顺序改成：octos.turn.start（手机）→ model（桌面）→ 本机规则。
//   走手机那条路时，把 task 与格式要求全写进那一句话，再把回话里的 JSON 抠出来。
//   功能一个不少 —— 类型、标题、提醒、出卡、写回、发回群，全都照旧；
//   变的只是「问法」和「听法」。谁在就找谁，都不在如实降级。
//
// 0.8.0 · 助手当「决策核心」（A2）
//   接上设备助手（model.complete）时，助手不只知道"这是哪一类事"——
//   它还负责「标题怎么起 / 要不要提醒 / 提前多久 / 提醒时说什么」。
//   这几件，正则词表在原理上做不到：词表只能命中关键词，
//   写不出人话标题，也判不出"这件事该提前一天、还是提前一小时提醒"。
//   助手不可用时（例如本机 Rinx 不给 model），退为「本机规则」——
//   仍判类型与时间、卡照出、事照记，只是没有标题与提醒建议，且如实标注降级。
//
// 长期记忆：存在应用自己的 jail 里（memory.json），与生成器同一套 schema
//   version / prefs / places / log
// 三个来源（两个"读"开关已开；模型开关默认关，见 ASK_MODEL 注释；各带 fail-closed 兜底）：
//   ① 本机记住的（你造的卡）—— 永远可用，不依赖任何服务
//   ② 设备助手的会话（octos.session.history）+ 一次性模型（model.complete）
//   ③ 绑定房间里的聊天（matrix.read_messages）—— 读一条直接造卡
//   ④ 你在 Matrix 上的名字（matrix.profile）—— 认出聊天里哪条是「你自己说的」
//   ⑤ 确认后真办事（matrix.send_message）—— 把这次意图的结论真发回那个群（「记下了」→「办成了」）
// 记忆用在三处：
//   ① 造卡时给出「记忆行」（包括和记忆冲突的提醒）—— 这才叫「知道用户喜好」
//   ② 确认时写回（偏好 / 常去的地方 / 卡片流水）
//   ③ 接模型时当上下文（mem_brief()：真接上助手，这就是喂给它的那段）
// 注释只能用 // 或 /* */（`#` 是颜色记号，不是注释）。

// ---------------------------------------------------------------- 配色
let bg      = #x0e1a16
let surface = #x16251f
let cardbg  = #x1b2c24
let membg   = #x14231d
let line    = #x274036
let ink     = #xeaf3ee
let dim     = #x9db3aa
let faint   = #x6d847b
let accent  = #x7fd1b9
let accentD = #x5fb9a2
let warn    = #xe6b06a

// ---------------------------------------------------------------- 状态
let raw = ""
let when = ""
let where = ""
let kind = ""
let built = false
let done = false
let note = "写一句话，或点下面的例子"
let hints = []          // 这次卡上「记忆参与」的行

// ---- 助手当决策核心时多出来的几件（0.8.0）—— 走规则兜底时一律为空
let title = ""          // 人话标题（助手起；规则兜底留空 ⇒ 卡上回退到原句）
let ai_why = ""         // 助手给的一句话依据
let remind = ""         // none | at_time | lead_hour | lead_day —— 助手对"要不要提醒、提前多久"的判断
let remind_text = ""    // 提醒时该说的那句话（助手写；这是词表写不出来的）
let remind_after = 0    // 助手算的「从现在起多少秒后提醒」（0 = 这次没算到确切时刻）
let remind_state = ""   // 到点提醒排出去后的回执（宿主排到那一刻，**真到点才响**）
let speak_on = true     // 语音提醒开关（记忆里存，卡片上可切；"可以不发可以发"）
let ai_skip = false     // 助手判断"这条不必安排"（kind=none）⇒ 不造卡，如实说明

// ---- 识别来源（复赛接 AI 就走这条）
let src = "rules"              // rules | model | model-standin
let model_state = ""           // 助手不可用时的说明，如实显示在卡上
let MODEL_STANDIN = false      // 开发期替身：从 jail 的 model-stub.json 读一条回复，
                               // 用来验证「回复 → 卡」这一整条链（本机没有 model 服务）。
let ASK_MODEL = true           // 🚩 复赛已开：优先问宿主自带的设备助手。
                               // 两条路，看宿主给哪条：
                               //   ① octos.turn.start —— 手机壳（Rinx）自带：一句话进去、一段文本回来；
                               //      官方示例 examples/miniapps/matrix-octos-script/main.splash:22 就是它。
                               //   ② model.complete  —— 桌面壳（OctoSense shell）提供：一次问、要 schema。
                               // 都没有 ⇒ 退本机规则，并如实标注降级（绝不假装"已接大模型"）。
                               // 为什么探测而不是写死：同一个 bundle 要同时活在两种宿主上，
                               // manifest.capabilities 两条都声明，谁在就找谁。

// ---- 读设备助手的会话记忆（octos.session.history）—— 第二个「长期记忆」来源
// 本机记住的是「你造的卡」；助手那边记住的是「你在对话里说过的」。两个合起来才叫真知道你是谁。
// 官方契约：capability 就是同名的 `octos.session.history`；args {}；
//   返回 {session_id, messages:[{…, lane, speaker, role, content}, …]}（两条车道按时间合并）。
// 脚本 app 不许用 bindings.json，只能像这样直接 host.request（HOST-SERVICES.md）。
let READ_ASSIST_HISTORY = true   // 🚩 复赛已开：读设备助手与你的会话（manifest 已声明同名能力）
let HIST_STANDIN = false         // 开发期替身：从 jail 的 history-stub.json 读一段会话，
                                 // 用来验「读 → 用」这条链（card-host 没有助手服务）。
let ahist_ok = false
let ahist_count = 0
let ahist_lines = []             // 展示用：最近几条（说话人 + 截断后的话）
let ahist_state = ""             // 读不到时的如实说明

// ---- 从聊天里拾意（matrix.read_messages）—— 「读消息」这条能力
// 官方契约：服务名就是 `matrix.read_messages`；args {room_id, limit(1..30)}；
//   需 app 在导入时**绑定一个房间** —— 读的就是那个房间的最近消息。
//   返回：messages 数组（每项有 sender / body / ts / room_id / unread 等）+ unread_count，旧→新排列。
// 脚本 app 不许用 bindings.json，只能直接 host.request（HOST-SERVICES.md）。
let READ_CHAT = true         // 🚩 复赛已开：从绑定的群里读最近消息，挑一条直接造卡
                             // 没绑房间 / 宿主没有这服务 ⇒ 只写一行如实说明，绝不挡路
let CHAT_STANDIN = false     // 开发期替身：从 jail 的 chat-stub.json 读一段消息（card-host 没有 matrix 服务）
let chat_ok = false
let chat_count = 0
let chat_rows = []           // 展示用：最近几条（说话人 + 截断后的话）
let chat_texts = []          // 与 chat_rows 一一对应：原始消息文本（点了就当成输入）
let chat_msgs = []           // 原始消息数组（profile 回来后重算「（你）」标记用）
let chat_state = ""          // 读不到时的如实说明

// ---- 自动读群消息（本地 2026-10-11 加 · 与桌面「自动读邮件」同构）
let chat_auto = true          // 自动读：群里有新消息就自己造卡（不必等人点）
let chat_auto_booted = false  // 首启只登记基线：房间里原有的旧消息不刷成卡
let chat_auto_last = ""       // 游标：上次见到的最后一条群消息正文（读消息固定返回最近 N 条，靠它认新旧）
let chat_auto_state = ""      // 如实说明（读到几条 / 出了什么卡）
let chat_auto_log = []        // 最近自动造的几张卡（展示用）
let chat_poll_n = 0           // 自己看了几次群（心跳，给用户一个"它真在跑"的凭据）

// ---- 你在 Matrix 上的名字（matrix.profile）—— 「认自己」
// 官方契约（Rinx crates/miniapp-core/src/matrix.rs:185）：服务名就是 `matrix.profile`；
//   args {}（**不用绑房间**，属 room_free 组）；返回 {user_id, display_name}；成本 1.0。
// 用途：读聊天时把「你自己发的」在列表里标出来 —— 自己说的 vs 别人说的，在「拾意」里是两回事。
// 同一组 room_free 的还有 rooms_list / account_info / device / spaces，先只接最稳、牵线也用过的那一个。
let READ_PROFILE = true      // 🚩 复赛已开：读你自己的名字（manifest 已声明同名能力）
let PROFILE_STANDIN = false  // 开发期替身：从 jail 的 profile-stub.json 读（card-host 没有 matrix 服务）
let me_ok = false
let me_id = ""
let me_name = ""
let me_state = ""            // 读不到时的如实说明

// ---- 确认后真办事（matrix.send_message）—— 这是「意图即应用」里「应用」那半截
// 官方契约（Rinx crates/miniapp-core/src/matrix.rs:219）：服务名就是 `matrix.send_message`；
//   args {body}；**需 app 绑定房间**（非 room_free 组）。
// 一件意图只有「真的送出去」才算办成 —— 确认一张卡 = 把结论发回你绑定的那个群。
// 发不出去就如实退回「只留在本机」，绝不假装成功。
let LET_IT_ACT = true        // 确认后真发回群（manifest 已声明同名能力）
let SEND_STANDIN = false     // 开发期替身：把回执写进 jail 的 send-stub.json（card-host 没有 matrix 服务）
let sent_ok = false          // 是否真的发出去了
let sent_state = ""          // 在途 / 成功 / 失败 的如实说明


// ---------------------------------------------------------------- 长期记忆
let MEM = "memory.json"
let mem = {}            // 与生成器同 schema
let mem_ok = false
let mem_count = 0
let mem_lines = []      // 偏好（展示用）
let mem_places = []     // 常去的地方（展示用）

// ---------------------------------------------------------------- 样式
let Pill = ButtonFlat{height: 36
    draw_bg +: {border_radius: 18.0 color: accent color_hover: #x8fdec9 color_down: accentD border_size: 0.0}
    draw_text +: {color: #x0e1a16 font_size: 13}}
let Ghost = ButtonFlat{height: 36
    draw_bg +: {border_radius: 18.0 color: #x22352c color_hover: #x2c463a color_down: #x1a2a23 border_size: 0.0}
    draw_text +: {color: dim font_size: 13}}
let Tiny = ButtonFlat{height: 30
    draw_bg +: {border_radius: 15.0 color: #x1d2f27 color_hover: #x2c463a color_down: #x16251f border_size: 0.0}
    draw_text +: {color: accent font_size: 12}}
let Mini = ButtonFlat{height: 26
    draw_bg +: {border_radius: 13.0 color: #x22352c color_hover: #x2c463a color_down: #x1a2a23 border_size: 0.0}
    draw_text +: {color: faint font_size: 11}}
let Msg = ButtonFlat{width: Fill height: 32
    draw_bg +: {border_radius: 10.0 color: #x1b2c24 color_hover: #x22352c color_down: #x16251f border_size: 0.0}
    draw_text +: {color: ink font_size: 12}}
let Field = TextInput{width: Fill height: 42
    empty_text: "写一句话，比如：周四去建材市场挑瓷砖"
    draw_bg +: {color: #x0f1b17 color_hover: #x0f1b17 color_focus: #x0f1b17 color_empty: #x0f1b17
        border_color: #x2a4238 border_color_hover: #x33513f border_color_focus: accent border_color_empty: #x2a4238
        border_radius: 10.0 border_size: 1.0}
    draw_text +: {color: ink color_hover: ink color_focus: ink color_empty: faint color_empty_hover: faint}}

// ---------------------------------------------------------------- 词表
let CITIES = ["深圳","北京","上海","广州","杭州","成都","重庆","武汉","西安","南京","苏州","天津","长沙","青岛","厦门","香港"]
let WD_CH = ["一","二","三","四","五","六","日","天"]

// ---------------------------------------------------------------- 小工具
fn pad2(n){
    if n < 10 { return "0" + ("" + n) }
    return "" + n
}

fn ts(){
    let lt = local_time()
    return ("" + lt.year) + "-" + pad2(lt.month) + "-" + pad2(lt.day)
        + " " + pad2(lt.hour) + ":" + pad2(lt.minute)
}

fn joined(arr, sep){
    let s = ""
    let i = 0
    for v in arr {
        if i > 0 { s = s + sep }
        s = s + v
        i = i + 1
    }
    return s
}

fn has_key(o, key){
    for k v in o {
        if k == key { return true }
    }
    return false
}

fn kind_zh(k){
    if k == "trip" { return "出行" }
    if k == "meeting" { return "会面" }
    if k == "errand" { return "代办" }
    if k == "purchase" { return "采买" }
    if k == "reminder" { return "提醒" }
    if k == "pref" { return "习惯" }
    return "记录"
}

// 助手给的「提醒策略」→ 卡上那行中文（词表给不出这个判断）
fn remind_zh(p){
    if p == "at_time" { return "到点提醒" }
    if p == "lead_hour" { return "提前 1 小时（临期）" }
    if p == "lead_day" { return "提前 1 天" }
    return ""
}

// 「从现在起多少秒」→ 人话（卡上那行排程回执）
fn dur_zh(s){
    if s < 90 { return ("" + s) + " 秒" }
    if s < 5400 { return ("" + (s / 60.0)) + " 分钟" }
    if s < 129600 { return ("" + (s / 3600.0)) + " 小时" }
    return ("" + (s / 86400.0)) + " 天"
}

fn today_m(){
    let wd = local_time().weekday
    if wd == 0 { return 7 }
    return wd
}

fn wd_num(ch){
    if ch == "一" { return 1 }
    if ch == "二" { return 2 }
    if ch == "三" { return 3 }
    if ch == "四" { return 4 }
    if ch == "五" { return 5 }
    if ch == "六" { return 6 }
    return 7
}

fn date_str(epoch){
    let lt = local_time(epoch)
    return ("" + lt.month) + "月" + ("" + lt.day) + "日"
}

fn week_when(t, ch){
    let m = today_m()
    let tgt = wd_num(ch)
    let nx = tgt - m
    if nx <= 0 { nx = nx + 7 }
    let rel = "周" + ch
    if regex("下下周", "i").test(t) {
        nx = nx + 14
        rel = "下下周" + ch
    } else if regex("下周|下星期|下礼拜", "i").test(t) {
        if tgt > m {
            nx = nx + 7
            rel = "下周" + ch
        }
    }
    return rel + " · " + date_str(time_now() + nx * 86400.0)
}

// ---------------------------------------------------------------- 记忆：读
// 读一律用「枚举」，不点字段 —— 缺字段在 splash 里是**报错**不是 nil
fn pref_on(key){
    if !has_key(mem, "prefs") { return false }
    for k v in mem.prefs {
        if k == key { return v == true }
    }
    return false
}

fn place_seen(name){
    if !has_key(mem, "places") { return 0 }
    for k v in mem.places {
        if k == name {
            for fk fv in v {
                if fk == "seen" { return fv }
            }
        }
    }
    return 0
}

fn place_field(name, field){
    if !has_key(mem, "places") { return "" }
    for k v in mem.places {
        if k == name {
            for fk fv in v {
                if fk == field { return "" + fv }
            }
        }
    }
    return ""
}

fn mem_load(){
    mem = {}
    mem_ok = false
    mem_count = 0
    mem_lines = []
    mem_places = []

    if fs.exists(MEM) {
        let doc = fs.read(MEM).parse_json()
        if doc != nil {
            mem = doc
            mem_ok = true
        }
    }
    if !has_key(mem, "prefs") { mem.prefs = {} }
    if has_key(mem.prefs, "speak_on") { speak_on = mem.prefs.speak_on } else { mem.prefs.speak_on = true }
    // 自动读群消息的游标（存记忆里，重启后接着读，不从头再刷一遍）
    if has_key(mem, "chat_last") { chat_auto_last = mem.chat_last }
    if has_key(mem, "chat_booted") { chat_auto_booted = mem.chat_booted }
    if !has_key(mem, "places") { mem.places = {} }
    if !has_key(mem, "log") { mem.log = [] }

    for k v in mem.prefs {
        if v == true {
            if k == "no_flight" { mem_lines.push("不坐飞机") }
            if k == "prefers_rail" { mem_lines.push("坐高铁") }
            if k == "no_wednesday_pm" { mem_lines.push("周三下午别安排") }
        }
    }
    for k v in mem.places {
        let dep = place_field(k, "default_depart")
        let ln = k
        if dep != "" { ln = ln + " · 通常" + dep }
        let seen = place_seen(k)
        if seen > 0 { ln = ln + " · 去过 " + ("" + seen) + " 次" }
        mem_places.push(ln)
    }
    mem_count = mem.log.len()
}

// 第 i 条（从最新往回数）：只枚举字段，不点缺的键
fn mem_log_line(i){
    if !has_key(mem, "log") { return "" }
    let n = mem.log.len()
    let idx = n - 1 - i
    if idx < 0 { return "" }
    if idx >= n { return "" }
    let e = mem.log[idx]
    let k = ""
    let t = ""
    let msg = ""
    let plc = ""
    for fk fv in e {
        if fk == "kind" { k = fv }
        if fk == "text" { t = fv }
        if fk == "message" { msg = fv }
        if fk == "place" { plc = fv }
    }
    if t == "" { t = msg }
    if t == "" {
        if plc != "" { t = "去了" + plc }
    }
    if t == "" { t = "一条早期记录" }
    return kind_zh(k) + " · " + t
}

// 供「接模型」用：真接上助手时，这段就是随用户那句话一起发给模型的上下文。
// 两个来源合起来：本机记住的（你造的卡）+ 助手会话里读到的（你在对话里说过的）。
fn mem_brief(){
    let parts = []
    if mem_lines.len() > 0 { parts.push("偏好：" + joined(mem_lines, "、")) }
    if mem_places.len() > 0 { parts.push("常去 " + joined(mem_places, "；")) }
    if ahist_lines.len() > 0 { parts.push("助手会话里提到：" + joined(ahist_lines, "；")) }
    let s = "用户长期记忆：" + joined(parts, "。")
    if parts.len() == 0 { s = "用户长期记忆：（暂时空白）" }
    return s
}

// ---------------------------------------------------------------- 助手会话记忆
// 截断：splash 没有 slice，用 regex 取前 n 个字（match_str 非全局返回 {value,…}）。
fn clip(s, n){
    let m = s.match_str(regex("^.{0," + ("" + n) + "}", ""))
    if m == nil { return s }
    if m.value.len() < s.len() { return m.value + "…" }
    return m.value
}

// 把 octos.session.history 的返回嚼成展示行 —— 一律「枚举」，不点缺失的键（缺字段在 splash 里是报错不是 nil）
fn ahist_ingest(doc){
    ahist_lines = []
    ahist_count = 0
    ahist_ok = true
    ahist_state = ""
    if !has_key(doc, "messages") { return }
    let msgs = doc.messages
    let n = msgs.len()
    ahist_count = n
    let from = 0
    if n > 3 { from = n - 3 }
    let i = 0
    for m in msgs {
        if i >= from {
            let c = ""
            let who = ""
            for fk fv in m {
                if fk == "content" { c = fv }
                if fk == "speaker" { who = fv }
