                if tag == "" { tag = "有人" }
                if me_ok {
                    if me_id != "" {
                        if sid == me_id { tag = tag + "（你）" }
                    }
                }
                chat_rows.push(tag + "：" + clip(b, 20))
                chat_texts.push(b)
            }
        }
        i = i + 1
    }
}

