// ---------------------------------------------------------------- 自动读群消息（本地 2026-10-11 加）
// 与桌面「自动读邮件」同一套：**不是等人点，是自己隔几秒读一次**。
// 只处理「最后一条和上次不一样」的那些（游标 chat_auto_last）；首启只登记基线，
// 免得一开机把房间里几天前的旧消息全刷成卡。拾意自己发回群的结论也不再造卡。
fn chat_auto_head(){
    if !READ_CHAT { return "自动读群消息：关（读消息总开关关着）" }
    if !chat_auto { return "自动读群消息：关" }
    if !host.has("matrix.read_messages") { return "自动读群消息：开 · 宿主没提供读消息" }
    return "自动读群消息：开 · 群里来新消息，它自己读到就造卡（已看 " + ("" + chat_poll_n) + " 次）"
}

fn chat_auto_save(){
    mem.chat_last = chat_auto_last
    mem.chat_booted = chat_auto_booted
    mem_write()
}

fn m_body(m){
    let b = ""
    for fk fv in m { if fk == "body" { b = fv } }
    return b
}

// 拾意自己发回群的那条结论（「✅ 拾意已记下…」）—— 不把它再当成新消息造一遍卡
fn is_echo(m){
    let b = m_body(m)
    if b == "" { return true }
    return regex("^✅", "").test(b)
}

fn chat_auto_ingest(doc){
    if doc == nil { return }
    if !has_key(doc, "messages") { return }
    let msgs = doc.messages
    let n = msgs.len()
    if n == 0 { return }
    // 读消息固定只返回最近 N 条 —— 条数会一直卡在 N，所以**不能数条数**，
    // 认的是「最后一条的正文」变了没有。
    let last = msgs[n - 1]
    let b = m_body(last)
    if b == "" { return }
    if !chat_auto_booted {           // 首启：只登记基线，房间里原有的旧消息不刷成卡
        chat_auto_booted = true
        chat_auto_last = b
        chat_auto_save()
        ui.chatbox.render()
        return
    }
    if b == chat_auto_last { return }   // 还是那条，没有新消息
    chat_auto_last = b
    chat_auto_save()
    if is_echo(last) {                  // 拾意自己发回群的结论：只挪游标，不再造卡
        ui.chatbox.render()
        return
    }
    chat_auto_log.push(clip(b, 24))
    if chat_auto_log.len() > 3 {
        let keep = []
        let k = chat_auto_log.len() - 3
        let j = 0
        for x in chat_auto_log {
            if j >= k { keep.push(x) }
            j = j + 1
        }
        chat_auto_log = keep
    }
    chat_auto_state = "群里来了新消息，它自己读到，正在造卡"
    ui.chatbox.render()
    use_one(b)                       // ← 与「点一条」走同一条路：造卡 → 出卡
}

// 每 6 秒自己看一眼群（与桌面 mail_poll 每 10 秒同构）
fn chat_poll(){
    chat_poll_n = chat_poll_n + 1
    ui.chatbox.render()
    if !READ_CHAT { return }
    if !chat_auto { return }
    if !host.has("matrix.read_messages") { return }
    host.request("matrix.read_messages", {limit: 10}, fn(r){
        if r.is_ok { chat_auto_ingest(r.data) }
    })
}

// 自己给自己排下一次 —— 用 start_timeout 自递归（这个两端都验证可用；
// 手机壳里没有 start_interval 这个名字，直接用它会静默不生效）。
