fn mem_write(){
    if !has_key(mem, "version") { mem.version = 1 }
    mem.updated_at = ts()
    if !mem_ok { mem.seeded_from = "shiyi-live" }
    if mem.log.len() > 200 {
        let keep = []
        let n = 200
        for i in n { keep.push(mem.log[mem.log.len() - n + i]) }
        mem.log = keep
    }
    fs.write(MEM, mem.to_json())
    mem_ok = true
}

fn place_obj(name){
    let r = {}
    r.seen = 1
    r.at = ts()
    r.last_kind = kind
    if has_key(mem, "places") {
        for k v in mem.places {
            if k == name {
                for fk fv in v {
                    if fk == "seen" { r.seen = fv + 1 }
                    if fk == "default_depart" { r.default_depart = fv }
                    if fk == "from" { r.from = fv }
                }
            }
        }
    }
    return r
}

fn mem_remember(){
    let e = {}
    e.at = ts()
    e.kind = kind
    e.text = raw
    e.when = when
    e.where = where
    e.confirmed = true
    mem.log.push(e)
    if where != "" { mem.places[where] = place_obj(where) }
    learn_from(raw)
    mem_write()
    mem_load()
}

fn forget(){
    if fs.exists(MEM) { fs.remove(MEM) }
    mem = {}
    mem_load()
    ui.membox.render()
    ui.card.render()
}

// ---------------------------------------------------------------- 识别
// ---------------------------------------------------------------- 接 AI（model.complete）
// 官方契约（AI-SERVICES.md）：一次性、回复必须过 schema、应用看不到 provider/model/key。
// 失败是 "<code>: <句子>"（no_provider / budget / rate / bad_request / invalid_output / …）。
// 本地 card-host 没有 model 服务，会答 no service answers "model" —— 那就回退规则。
fn model_task(){
    return "你是「拾意」的识别与安排助手：读用户说的一句话，替他把这件事安排成一张卡。请判断并给出："
        + "① kind：trip 出行 / meeting 会面 / errand 代办 / purchase 采买 / reminder 提醒 / pref 习惯 / "
        + "note 杂记 / none 无事（纯寒暄、没有可安排的事，就用 none）；"
        + "② title：用一句人话给这件事起个标题，不超过 16 字，说人话，不要照抄原句；"
        + "③ when_text：中文时间，能确定日期就写成「周X · N月N日」，没有就留空串；"
        + "④ where：只写地点名，没有就留空串；"
        + "⑤ remind：要不要提醒？none 不用 / at_time 到点提醒 / lead_hour 提前 1 小时（临期）/ lead_day 提前 1 天；"
        + "⑥ remind_text：若需提醒，写提醒时对用户说的那句话——像人一样，带上关键信息（比如要带什么、给谁），"
        + "不超过 20 字；不用提醒就留空串；"
        + "⑦ why：一句话写你的依据；"
        + "⑧ remind_after_seconds：现在是「" + ts() + "」。若这事要提醒，算出**从现在起多少秒后**该提醒（整数）；"
        + "例：现在是「" + ts() + "」、事情在明天 15:00、提前 1 小时 ⇒ 明天 14:00，约为 19.5 小时 ≈ 70200 秒；不用提醒就填 0。"
        + "只依据这句话本身，不要编造；不要输出 URL；只输出符合 schema 的 JSON。"
}

fn model_schema(){
    return {type: "object" additionalProperties: false
        required: ["kind" "title" "when_text" "where" "remind" "remind_text" "why" "remind_after_seconds"]
        properties: {
            kind: {type: "string"}
            title: {type: "string"}
            when_text: {type: "string"}
            where: {type: "string"}
            remind: {type: "string"}
            remind_text: {type: "string"}
            why: {type: "string"}
            remind_after_seconds: {type: "integer"}
        }}
}

// 本地替身：从 jail 里读一条回复（没有就空对象 → 走"回复不合预期"的兜底）
fn standin_output(){
    if fs.exists("model-stub.json") {
        let o = fs.read("model-stub.json").parse_json()
        if o != nil { return o }
    }
    return {}
}

fn apply_model_output(o, t){
    let k = ""
    let ti = ""
    let wt = ""
    let wh = ""
    let rm = ""
    let rt = ""
    let wy = ""
    let ra = 0
    for fk fv in o {
        if fk == "kind" { k = fv }
        if fk == "title" { ti = fv }
        if fk == "when_text" { wt = fv }
        if fk == "where" { wh = fv }
        if fk == "remind" { rm = fv }
        if fk == "remind_text" { rt = fv }
        if fk == "why" { wy = fv }
        if fk == "remind_after_seconds" { ra = fv }
    }
    raw = t
    title = ti
    when = wt
    where = wh
    remind = rm
    remind_text = rt
    remind_after = ra
    ai_why = wy
    done = false
    hints = []
    if k == "none" {
        // 助手判断"这条不必安排" —— 这是词表给不出的判断（词表永远硬塞一个类别）
        kind = ""
        ai_skip = true
        built = false
        note = "助手看了：这条不必安排 —— 没造卡"
    } else {
        kind = k
        ai_skip = false
        built = true
        note = "助手读出一张「" + kind_zh(kind) + "」卡"
    }
    mem_hints(t)
    ui.card.render()
}

// ---- 手机壳（Rinx）的接法：octos.turn.start ----
// 只收 {text}、回 {text}（官方示例 examples/miniapps/matrix-octos-script/main.splash:22 同款）。
// 任务与格式要求全写进那一句话里 —— 这就是「换个问法」，别处一行不动。
fn turn_prompt(t){
    return model_task()
        + "务必只回一个 JSON 对象：键和值都用英文双引号，不要解释、不要 Markdown 代码块、不要多余的字。"
        + "要说的话是：「" + t + "」"
}

// 从助手的回话里抠出那个 JSON 对象：先直接解析，不行再用正则取第一个花括号段。
// （splash 没有 slice，按本文件既有做法用 regex + match_str：clip() 同款。）
fn json_from_text(s){
    let o = s.parse_json()
    if o != nil { return o }
    let m = s.match_str(regex("[{][^{]*[}]", ""))
    if m == nil { return nil }
    let g = m.value.parse_json()
    if g != nil { return g }
    return nil
}

fn ask_turn(t){
    host.request("octos.turn.start", {text: turn_prompt(t)}, fn(r){
        if r.is_ok {
            if has_key(r.data, "text") {
                let o = json_from_text(r.data.text)
                if o != nil {
                    src = "model"
                    model_state = ""
                    apply_model_output(o, t)
                } else {
                    src = "rules"
                    model_state = "助手回复没读懂，已走本机规则"
                    identify_rules(t)
                }
            } else {
                src = "rules"
                model_state = "助手回复不合预期"
                identify_rules(t)
            }
        } else {
            src = "rules"
            model_state = "宿主没提供助手，已走本机规则"
            identify_rules(t)
        }
        ui.card.render()
    })
}

fn ask_model(t){
    host.request("model.complete", {
        task: model_task()
        input: {text: t memory: mem_brief()}
        schema: model_schema()
        class: "fast"
    }, fn(r){
        if r.is_ok {
            if has_key(r.data, "output") {
                src = "model"
                model_state = ""
                apply_model_output(r.data.output, t)
            } else {
                src = "rules"
                model_state = "助手回复不合预期"
                identify_rules(t)
            }
        } else {
            src = "rules"
            model_state = "宿主没提供助手，已走本机规则"
            identify_rules(t)
        }
        ui.card.render()
    })
}

