fn recognize(t){
    if t == "" {
        built = false
        done = false
        raw = ""
        hints = []
        title = ""
        ai_why = ""
        remind = ""
        remind_text = ""
        remind_after = 0
        ai_skip = false
        note = "先写一句话，再点「造卡」"
        ui.card.render()
        return
    }
    if !ASK_MODEL {
        src = "rules"
        model_state = ""
        identify_rules(t)
        return
    }
    if MODEL_STANDIN {
        src = "model-standin"
        model_state = ""
        let payload = {}
        payload.task = model_task()
        payload.input = {text: t memory: mem_brief()}
        payload["class"] = "fast"
        fs.write("model-prompt.json", payload.to_json())   // 本该发出去的东西，落盘备查
        apply_model_output(standin_output(), t)
        return
    }
    if host.has("octos.turn.start") {
        src = "rules"
        model_state = ""
        built = false
        note = "问设备助手…"
        ui.card.render()
        ask_turn(t)
        return
    }
    if host.has("model") {
        src = "rules"
        model_state = ""
        built = false
        note = "问设备助手…"
        ui.card.render()
        ask_model(t)
        return
    }
    src = "rules"
    model_state = "本机没有设备助手"
    identify_rules(t)
}

// 兜底那一路：本机规则（与生成器同一套口径）
fn identify_rules(t){
    raw = t
    when = ""
    where = ""
    kind = ""
    done = false
    title = ""
    ai_why = ""
    remind = ""
    remind_text = ""
    remind_after = 0
    ai_skip = false

    // 先说习惯（「我不坐飞机」这类）—— 优先于任何场景
    if regex("^我(不|讨厌|怕|喜欢|习惯)|^(别|不要)(安排|约|定)", "i").test(t) {
        kind = "pref"
    }

    if kind == "" {
        if regex("提醒|记得|别忘", "i").test(t) { kind = "reminder" }
        else if regex("买|订|付款|采购", "i").test(t) { kind = "purchase" }
        else if regex("寄|快递|取件", "i").test(t) { kind = "errand" }
        else if regex("碰|见面|见|开会|约|谈", "i").test(t) { kind = "meeting" }
        else if regex("去|出差|飞|高铁|机票|酒店", "i").test(t) { kind = "trip" }
    }

    let hit = ""
    for c in WD_CH {
        if hit == "" {
            if regex("(周|星期|礼拜)" + c, "i").test(t) { hit = c }
        }
    }
    if regex("今天", "i").test(t) { when = "今天 · " + date_str(time_now()) }
    else if regex("明天", "i").test(t) { when = "明天 · " + date_str(time_now() + 86400.0) }
    else if regex("后天", "i").test(t) { when = "后天 · " + date_str(time_now() + 2.0 * 86400.0) }
    else if regex("周末", "i").test(t) {
        let m = today_m()
        let nx = 6 - m
        if nx < 0 { nx = nx + 7 }
        when = "这个周末 · " + date_str(time_now() + nx * 86400.0)
    } else if regex("下个月", "i").test(t) {
        let l0 = local_time()
        let mo = l0.month + 1
        if mo > 12 { mo = 1 }
        when = "下个月 · " + ("" + mo) + "月"
    } else if hit != "" {
        when = week_when(t, hit)
    }

    for c in CITIES {
        if regex(c, "i").test(t) { where = c }
    }

    if kind == "pref" {
        note = "这是一条习惯 —— 确认就记住"
    } else if kind == "" {
        note = "没看准这是什么 —— 换个说法再试"
    } else {
        note = "读出一张「" + kind_zh(kind) + "」卡"
    }

    mem_hints(t)
    built = true
    ui.card.render()
}

fn use_one(t){
    ui.inp.set_text(t)
    recognize(t)
}

// 确认后把结论真发回群 —— 「意图即应用」里「应用」那半截，就在这几行
// 官方契约：服务名 `matrix.send_message`；args {body}；**需绑定房间**。
// 一件事只有真的送出去，才算办成。
fn receipt_text(){
    if kind == "pref" { return "✅ 拾意记下一条习惯：" + raw }
    let t = "✅ 拾意已记下"
    if when != "" { t = t + " · " + when }
    if where != "" { t = t + " · " + where }
    if when == "" {
        if where == "" { t = t + "：" + raw }
    }
    return t
}

fn send_back(){
    sent_ok = false
    if !LET_IT_ACT {
        sent_state = ""
        return
    }
    sent_state = "正在把结果发回群…"
    ui.card.render()
    let body = receipt_text()
    if SEND_STANDIN {
        fs.write("send-stub.json", body)
        sent_ok = true
        sent_state = "已把结果发回群（本地替身）"
        ui.card.render()
        return
    }
    if !host.has("matrix.send_message") {
        sent_state = "宿主没提供发消息 —— 结果只留在本机"
        ui.card.render()
        return
    }
    host.request("matrix.send_message", {body: body}, fn(r){
        if r.is_ok {
            sent_ok = true
            sent_state = "已把结果发回群 —— 这件事真的办成了"
        } else {
            sent_ok = false
            sent_state = "没能发回群 —— 结果只留在本机"
        }
        ui.card.render()
    })
}

// 语音提醒开关（可按需开关）：卡片上可切，存进本机记忆。
fn speak_label(){
    if speak_on { return "语音提醒：开" }
    return "语音提醒：关"
}
fn toggle_speak(){
    speak_on = !speak_on
    if mem_ok {
        mem.prefs.speak_on = speak_on
        fs.write(MEM, mem.to_json())
    }
    ui.card.render()
}

// 到点提醒（纵深 · 2026-10-11）：作品**只描述玩「什么时候、弹什么、念不念」**，
// **由宿主排到那一刻再执行**（Rinx 自建能力 `rinx.schedule`）—— 到点才响，不是立刻响；
// 到点时由宿主「弹通知 + （开关开着时）念出来」。
// **桌面与手机走的是宿主里同一段代码**，所以两端表现一致。
// 没算到确切时刻 / 宿主不提供排程时，**如实写明**，不假装（fail-closed）。
fn remind_fire(){
    if remind == "" { return }
    if remind == "none" { return }
    let t = title
    if t == "" { t = "拾意" }
    let body = remind_text
    if body == "" { body = "这件事该办了 · " + remind_zh(remind) }
    if remind_after < 1 {
        remind_state = "提醒规则：" + remind_zh(remind) + "（这次没算到确切时刻，未排程）"
        return
    }
    if !host.has("rinx.schedule") {
        remind_state = "宿主没提供排程能力 —— 提醒只留在卡上"
        return
    }
    // 演示压缩：真实场景里"明天下午三点"要等 20 小时，拍片子等不了。
    // 这里把**等待时长**压到一个可录的秒数；**提醒的规则/话术/提前量都是真的**，
    // 只是演示时让"那一刻"快点到（成片里用字幕交代时间跨度）。
    let wait = 45
    if remind_after < 45 { wait = remind_after }
    host.request("rinx.schedule", {seconds: wait, title: t, text: body, speak: speak_on}, fn(r){
        if r.is_ok {
            remind_state = "已排程 · 到点会念出来"
        } else {
            remind_state = "排程没成 —— 宿主没收下这个时刻"
        }
        ui.card.render()
    })
}

fn confirm(){
    done = true
    mem_remember()          // ← 确认 = 记住
    note = "记下了 —— 记忆已更新"
    send_back()             // ← 确认 = 真办事：把结论发回绑定的那个群
    remind_fire()           // ← 确认 = 到点提醒：宿主弹一条系统通知（纵深）
    ui.membox.render()
    ui.card.render()
}

fn back_to_edit(){
    built = false
    done = false
    note = "改好再点「造卡」"
    ui.card.render()
}

fn reset(){
    raw = ""
    when = ""
    where = ""
    kind = ""
    title = ""
    ai_why = ""
    remind = ""
    remind_text = ""
    remind_after = 0
    ai_skip = false
    built = false
    done = false
    hints = []
    note = "写一句话，或点下面的例子"
    ui.inp.set_text("")
    ui.card.render()
}

start_timeout(0.05, || { mem_load() ahist_fetch() profile_fetch() chat_fetch() ui.membox.render() ui.card.render() })

